script:
// ========== COPY DESCRIPTION FROM LINKED SALES ORDER ==========
frappe.ui.form.on('Purchase Order', {
    before_save(frm) {
        
        const firstItem = frm.doc.items?.[0];
        if (firstItem?.image) {
            frm.set_value('custom_image_product', firstItem.image);
        }
        if (frm.doc.custom_item_bom) {
            frm.doc.custom_bom_items.forEach(row => {
                frappe.model.set_value(row.doctype, row.name, 'bom_no', frm.doc.custom_item_bom);
            });
        }
    },
    validate: function(frm) {
        update_has_our_responsibility_items(frm);
    },
    custom_fetch_bom_from_sales_order: function(frm) {
        update_note_based_on_jback(frm);
        if (frm.doc.custom_item_bom) {
            update_actual_bom_qty_from_bom(frm);
            frm.doc.custom_bom_items.forEach(row => {
                frappe.model.set_value(row.doctype, row.name, 'bom_no', frm.doc.custom_item_bom);
            });
    
            frm.save();
        }
    },
    onload: function(frm) {
        if (frm.doc.from_sales_order && frm.doc.items && frm.doc.items.length > 0) {
            frappe.db.get_doc('Sales Order', frm.doc.from_sales_order)
                .then(sales_order => {
                    sales_order.items.forEach((so_item, i) => {
                        let po_item = frm.doc.items[i];
                        if (po_item) {
                            po_item.description = so_item.description;
                        }
                    });
                    frm.refresh_field('items');
                });
        }
    },
    custom_bom_items_on_form_rendered(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        calculate_amount(row, cdt, cdn);
    }
});

// ========== SET READ-ONLY ON CHILD ROW OPEN ==========
function update_has_our_responsibility_items(frm) {
    let found = false;

    (frm.doc.custom_bom_items || []).forEach(item => {
        if (item.our_responsibility === 1) {
            found = true;
        }
    });

    frm.set_value('custom_has_our_responsibility_items', found ? 1 : 0);
}


frappe.ui.form.on('Purchase Order', {
    async custom_fetch_bom_from_sales_order(frm) {
        const first_item = frm.doc.items && frm.doc.items.length > 0 ? frm.doc.items[0] : null;

        if (!first_item || !first_item.sales_order) {
            frappe.msgprint('First row of Items table must have a Sales Order linked.');
            return;
        }

        const sales_order_name = first_item.sales_order;

        try {
            const so = await frappe.db.get_doc('Sales Order', sales_order_name);

            if (so.custom_item_bom) {
                frm.set_value('custom_item_bom', so.custom_item_bom);
            }

            frm.clear_table('custom_bom_items');

            const field_map = {
                item_code: 'item_code',item_group: 'custom_item_group',item_description: 'description',qty: 'qty',uom: 'uom',rate: 'rate',amount: 'amount',custom_gemstone: 'custom_gemstone',selling_rate: 'custom_selling_rate',
                selling_amount: 'custom_selling_amount',our_responsibility: 'custom_our_responsibility',item_group: 'custom_item_group',
                sku_carat_weight: 'custom_sku_weight',avg_carat_weight: 'custom_avg_carat_weight',setting_type: 'custom_setting_type',merch_color__attribute: 'custom_merch_color__attribute',
                custom_stone_treatment_list: 'custom_stone_treatment_list',stone_pieces: 'custom_stone_pieces',min_weight: 'custom_min_weight',custom_country_of_origin: 'custom_country_of_origin',metal_weight: 'custom_metal_weight',
                cut: 'custom_cut',length: 'custom_length',grade: 'custom_grade',weight_per_piece: 'custom_weight_per_piece',merch_color: 'custom_merch_color',avg_metal_weight: 'custom_metal_weight',sku_metal_weight: 'custom_sku_metal_weight',
                bom_no: 'bom_no',custom_with_jback : 'custom_with_jback',

            };

            for (let row of so.custom_bom_items || []) {
                const new_row = frm.add_child('custom_bom_items');

                for (let target_field in field_map) {
                    const source_field = field_map[target_field];
                    new_row[target_field] = row[source_field];
                }
                if (row.bom_no && row.item_code) {
                    try {
                        const bom_doc = await frappe.db.get_doc('BOM', row.bom_no);

                        const matched_bom_item = (bom_doc.items || []).find(
                            bom_item => bom_item.item_code === row.item_code
                        );
                        if (matched_bom_item) {
                            new_row.qty = matched_bom_item.qty;
                        } else {
                            console.warn(`Item ${row.item_code} not found in BOM ${row.bom_no}`);
                        }
                    } catch (e) {
                        console.error(`Failed to fetch BOM ${row.bom_no}`, e);
                    }
                }
            }

            frm.refresh_field('custom_bom_items');

        } catch (err) {
            console.error(err);
            frappe.msgprint('Error fetching Sales Order or processing data.');
        }
    }
});


function update_actual_bom_qty_from_bom(frm) {
    if (!frm.doc.custom_bom_items) return;

    frm.doc.custom_bom_items.forEach(row => {
        if (row.bom_no && row.item_code) {
            frappe.db.get_doc('BOM', row.bom_no).then(bom_doc => {
                if (bom_doc.items && bom_doc.items.length > 0) {
                    let matched_bom_item = bom_doc.items.find(bom_item => bom_item.item_code === row.item_code);
                    if (matched_bom_item) {
                        frappe.model.set_value(row.doctype, row.name, 'actual_bom_qty', matched_bom_item.qty);
                    } else {
                        frappe.model.set_value(row.doctype, row.name, 'actual_bom_qty', 0);
                    }
                }
            });
        }
    });
}
frappe.ui.form.on('Purchase Order', {
    custom_bom_items_on_form_rendered: function(frm) {
        update_custom_fields_from_metal_item(frm);
        update_actual_bom_qty_from_bom(frm);
    },
    custom_metal_lock:function(frm){
        update_custom_fields_from_metal_item(frm);
    },
    custom_metal_loss:function(frm){
        update_custom_fields_from_metal_item(frm);
    },
    onload: async function(frm) {
   
        update_actual_bom_qty_from_bom(frm);
        update_custom_fields_from_metal_item(frm);
        frm.add_custom_button(__('Metal Rate'), async function() {
            let table_data = [];
            frappe.call({
                method: "get_gold_rate",
                args: {
                    "docname": frm.doc.name
                },
                callback: function(r) {
                    if (r.data && r.data.length > 0) {
                        const dialog = new frappe.ui.Dialog({
                            title: 'Metal Rate',
                            fields: [
                                {
                                    fieldname: 'metal_rate_table',
                                    fieldtype: 'Table',
                                    label: 'Metal Rates',
                                    cannot_add_rows: 1,
                                    data: r.data,
                                    fields: [
                                        { fieldtype: 'Time', fieldname: 'time', label: 'Time', reqd: 1, in_list_view: true },
                                        { fieldtype: 'Data', fieldname: 'metal', label: 'Metal', reqd: 1, in_list_view: true },
                                        { fieldtype: 'Currency', fieldname: 'rate', label: 'Metal Rate', reqd: 1, in_list_view: true },
                                        { fieldtype: 'Link', fieldname: 'item', label: 'Item', options: 'Item', hidden: 1 }
                                    ]
                                }
                            ],
                            primary_action_label: 'Insert',
                            primary_action(values) {
                                const table_data = values.metal_rate_table || [];

                                if (!table_data.length) {
                                    frappe.msgprint('Please enter at least one metal rate.');
                                    return;
                                }
                                console.log(table_data)
                                table_data.forEach(r => {
                                    if (r.__checked) {
                                        let matched_item = frm.doc.items.find(item => item.item_code === r.item);
                                        if (matched_item) {
                                            frappe.model.set_value(matched_item.doctype, matched_item.name, "rate", r.rate);
                                        }
                                    }
                                });

                                frm.refresh_field("items");
                                dialog.hide(); 
                            }
                        });

                        dialog.set_secondary_action_label('Close');
                        dialog.set_secondary_action(() => {
                            dialog.hide();
                        });

                        dialog.show();
                    }
                }
            });
        });
        // frm.fields_dict['custom_bom_items'].grid.get_field('rate').df.onchange = function() {
        //     calculate_difference(frm);
        // };
        // frm.fields_dict['custom_bom_items'].grid.get_field('selling_rate').df.onchange = function() {
        //     calculate_difference(frm);
        // };
    },

});

function calculate_amount(row, cdt, cdn) {
    let qty = flt(row.qty) || 0;
    let rate = flt(row.rate) || 0;

    frappe.model.set_value(cdt, cdn, 'amount', qty * rate);
}

frappe.ui.form.on('Purchase Order BOM Items', {
    custom_our_responsibility: function(frm) {
        update_has_our_responsibility_items(frm);
    },
    custom_with_jback(frm, cdt, cdn) {
        update_note_based_on_jback(frm);
    },
    item_code: function(frm, cdt, cdn) {
        update_custom_fields_from_metal_item(frm);
    },
    qty: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        calculate_amount(row, cdt, cdn);
    },
    rate: function(frm, cdt, cdn) {
        calculate_difference(frm);
        let row = locals[cdt][cdn];
        calculate_amount(row, cdt, cdn);
    },
    selling_rate: function(frm, cdt, cdn) {
        calculate_difference(frm);
        let row = locals[cdt][cdn];
        calculate_amount(row, cdt, cdn);
    },
    stone_pieces: function(frm, cdt, cdn) {
        calculate_ext_qty_required_and_net_balance(frm, cdt, cdn);
    },
    oh: function(frm, cdt, cdn) {
        calculate_ext_qty_required_and_net_balance(frm, cdt, cdn);
    },
    total_qty: function(frm) {
        frm.doc.custom_bom_items.forEach(row => {
            calculate_ext_qty_required_and_net_balance(frm, row.doctype, row.name);
        });
    },
    form_rendered: function(frm, cdt, cdn) {
        const readOnlyFields = [
            'qty','item_code','item_group','custom_country_of_origin','supplier','uom',
            'custom_gemstone','custom_stone_treatment_list','grade','cut','setting_type','sku_metal_weight',
            'merch_color__attribute','sku_carat_weight','avg_carat_weight','stone_pieces'
        ];

        const grid_row = frm.fields_dict.custom_bom_items.grid.grid_rows_by_docname[cdn];
        if (grid_row?.grid_form) {
            readOnlyFields.forEach(field => {
                const df = grid_row.grid_form.fields_dict[field]?.df;
                if (df) {
                    df.read_only = 1;
                    grid_row.grid_form.fields_dict[field].refresh();
                }
            });
        }
    }
});

function update_custom_fields_from_metal_item(frm) {
    if (!frm.doc.custom_bom_items) return;

    let metalRateSet = false;

    frm.doc.custom_bom_items.forEach(row => {
        if (row.item_group === "Metal") {
            frappe.db.get_doc('Item', row.item_code).then(item_doc => {
                let purity_multiplier = flt(item_doc.custom_purity_multiplier);
                let metal_group = item_doc.custom_metal_group;

                frm.set_value('custom_purity_multiplier', purity_multiplier || 0);
                frm.set_value('custom_metal_group', metal_group || '');

                let custom_metal_lock = flt(frm.doc.custom_metal_lock);
                let custom_metal_loss = flt(frm.doc.custom_metal_loss);

                let calculated_rate = custom_metal_lock / 31.10348 * purity_multiplier * (1 + custom_metal_loss);
                calculated_rate = Math.round(calculated_rate * 100) / 100;

                frappe.model.set_value(row.doctype, row.name, 'rate', calculated_rate);

                if (!metalRateSet) {
                    frm.set_value('custom_metal_pricegram', calculated_rate);
                    metalRateSet = true;
                }
            });
        }
    });
}

function calculate_ext_qty_required_and_net_balance(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    if (row.item_group && row.item_group.toLowerCase() === 'stone') {
        let stone_pieces = flt(row.stone_pieces);
        let total_qty = flt(frm.doc.total_qty);
        let oh = flt(row.oh);

        let ext_qty_required = stone_pieces * total_qty;
        frappe.model.set_value(cdt, cdn, 'ext_qty_required', ext_qty_required);

        let net_balance_required = ext_qty_required - oh;
        frappe.model.set_value(cdt, cdn, 'net_balance_required', net_balance_required);
    } else {
        frappe.model.set_value(cdt, cdn, 'ext_qty_required', 0);
        frappe.model.set_value(cdt, cdn, 'net_balance_required', 0);
    }
}

function update_note_based_on_jback(frm) {
    const child_items = frm.doc.custom_bom_items || [];

    const has_jback = child_items.some(row => row.custom_with_jback);

    if (has_jback) {
        frm.set_value('custom_note', 'Add Under Gallery JBack');
    } else {
        frm.set_value('custom_note', '');
    }
}

frappe.ui.form.on('Purchase Order Item', {
    custom_update_rate: function(frm, cdt, cdn) {
        const child = locals[cdt][cdn];
        const new_rate = flt(child.rate); 

        if (!new_rate || new_rate === 0) {
            frappe.msgprint(__('Please enter a valid non-zero rate in this row.'));
            return;
        }

        frm.doc.items.forEach(row => {
            row.rate = new_rate;
        });

        frm.refresh_field('items');
    }
})

// Utilities --------------------------

function get_delivery_date_plus_10_days(transaction_date) {
    return frappe.datetime.add_days(transaction_date, 10);
}

// Update `custom_has_our_responsibility_items` flag
function update_has_our_responsibility_items(frm) {
    let found = false;
    (frm.doc.custom_bom_items || []).forEach(item => {
        if (item.custom_our_responsibility === 1) {
            found = true;
        }
    });
    frm.set_value('custom_has_our_responsibility_items', found ? 1 : 0);
}

// Update BOM item suppliers if not overridden
function update_bom_suppliers(frm) {
    (frm.doc.custom_bom_items || []).forEach(row => {
        if (!row.custom_is_supplier_overridden) {
            if (row.custom_our_responsibility == 1) {
                row.custom_supplier = frm.doc.custom_stone_vendor || '';
            }
        }
    });
    frm.refresh_field('custom_bom_items');
}

// Update BOM description fields based on custom fields
function update_bom_description(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    let original_description = row.description || '';

    const gemstone = row.custom_gemstone || '';
    const country = row.custom_country_of_origin || '';
    const avg_carat_weight = row.custom_avg_carat_weight || '';
    const sku_weight = row.custom_sku_weight || '';

    let updated_description = original_description;

    if (updated_description.includes("Gemstone:")) {
        updated_description = updated_description.replace(/(Gemstone:\s*)([^|]*)/, `$1${gemstone}`);
    } else {
        updated_description += ` | Gemstone: ${gemstone}`;
    }

    if (updated_description.includes("Country:")) {
        updated_description = updated_description.replace(/(Country:\s*)([^|]*)/, `$1${country}`);
    } else {
        updated_description += ` | Country: ${country}`;
    }

    if (updated_description.includes("Avg Carat Weight:")) {
        updated_description = updated_description.replace(/(Avg Carat Weight:\s*)([^|]*)/, `$1${avg_carat_weight}`);
    } else {
        updated_description += ` | Avg Carat Weight: ${avg_carat_weight}`;
    }

    if (updated_description.includes("SKU Weight:")) {
        updated_description = updated_description.replace(/(SKU Weight:\s*)([^|]*)/, `$1${sku_weight}`);
    } else {
        updated_description += ` | SKU Weight: ${sku_weight}`;
    }

    frappe.model.set_value(cdt, cdn, 'description', updated_description);
}

// Update item supplier to custom_factory_vendor if set
function update_supplier_in_items(frm) {
    if (!frm.doc.custom_factory_vendor) return;

    (frm.doc.items || []).forEach(item => {
        item.supplier = frm.doc.custom_factory_vendor;
    });

    frm.refresh_field('items');
}

// Get or create default warehouse with name "Stores" for a company
async function get_default_warehouse(company) {
    const res = await frappe.db.get_value('Warehouse', {
        warehouse_name: 'Stores',
        company: company,
        is_group: 0,
        disabled: 0  
    }, 'name');

    if (res && res.message && res.message.name) {
        return res.message.name;
    }

    try {
        const new_warehouse = await frappe.call({
            method: 'frappe.client.insert',
            args: {
                doc: {
                    doctype: 'Warehouse',
                    warehouse_name: 'Stores',
                    company: company,
                    is_group: 0,
                    disabled: 0
                }
            }
        });

        if (new_warehouse && new_warehouse.message && new_warehouse.message.name) {
            frappe.show_alert({
                message: `New warehouse created: ${new_warehouse.message.name}`,
                indicator: 'green'
            });
            return new_warehouse.message.name;
        }
    } catch (create_error) {
        console.error('Error creating warehouse:', create_error);
    }

    throw new Error("No valid warehouse found for company: " + company);
}

// Set Warehouse field from company abbreviation (e.g. "Stores - BBJ")
async function set_warehouse_from_company(frm) {
    if (!frm.doc.company) {
        frm.set_value('set_warehouse', '');
        return;
    }

    try {
        const res = await frappe.db.get_value('Company', frm.doc.company, 'abbr');
        const abbr = res?.message?.abbr;

        if (abbr) {
            frm.set_value('set_warehouse', `Stores - ${abbr}`);
        }
    } catch (err) {
        console.error("Error fetching company abbreviation:", err);
        frm.set_value('set_warehouse', '');
    }
}


// Function to create customer from supplier if not exists
async function create_customer_if_not_exists_server(supplier_name) {
    if (!supplier_name) {
        throw new Error('Supplier name is required');
    }

    try {
        const existing_customer = await frappe.db.get_value('Customer', {
            customer_name: supplier_name
        }, 'name');

        if (existing_customer && existing_customer.message && existing_customer.message.name) {
            console.log(`Customer already exists: ${existing_customer.message.name}`);
            return existing_customer.message.name;
        }

        const supplier_doc = await frappe.db.get_doc('Supplier', supplier_name);
        
        if (!supplier_doc) {
            throw new Error(`Supplier ${supplier_name} not found`);
        }

        const new_customer_doc = {
            doctype: 'Customer',
            customer_name: supplier_doc.supplier_name || supplier_name,
            customer_type: 'Company',
            customer_group: 'Individual', 
            territory: supplier_doc.country || 'All Territories',
            tax_id: supplier_doc.tax_id || '',
            website: supplier_doc.website || '',
            custom_created_from_supplier: supplier_name
        };

        const created_customer = await frappe.call({
            method: 'frappe.client.insert',
            args: { doc: new_customer_doc }
        });

        if (created_customer && created_customer.message && created_customer.message.name) {
            frappe.show_alert({
                message: `New customer created: ${created_customer.message.name}`,
                indicator: 'green'
            });
            return created_customer.message.name;
        } else {
            throw new Error('Failed to create customer');
        }

    } catch (error) {
        console.error('Error in create_customer_if_not_exists_server:', error);
        throw error;
    }
}

// Updated Sales Order creation function
async function create_sales_order_from_factory_vendor(frm) {
    if (!frm.doc.custom_factory_vendor) {
        frappe.msgprint(__('custom_factory_vendor is not set, cannot create Sales Order'));
        return;
    }

    const responsible_bom_items = (frm.doc.custom_bom_items || []).filter(
        item => item.custom_our_responsibility === 1
    );

    if (!responsible_bom_items.length) {
        frappe.msgprint(__('Cannot create Sales Order because no BOM item has Our Responsibility checked.'));
        return;
    }

    try {
        await create_customer_if_not_exists_server(frm.doc.custom_factory_vendor);

        let transaction_date = frappe.datetime.now_date();
        let delivery_date = get_delivery_date_plus_10_days(transaction_date);

        let new_so_doc = {
            doctype: "Sales Order",
            customer: frm.doc.custom_factory_vendor,
            transaction_date: transaction_date,
            company: frm.doc.company,
            custom_country_of_manufacturer: frm.doc.custom_country_of_manufacturer,
            custom_sales_order_type: "Stone",
            delivery_date: delivery_date,
            items: responsible_bom_items.map(item => ({
                item_code: item.item_code,
                qty: item.qty,
                rate: item.rate || 0,
                warehouse: item.warehouse || frm.doc.set_warehouse,
                description: item.description,
                supplier: item.custom_supplier || frm.doc.custom_factory_vendor,
                uom: item.uom,
                custom_size: item.custom_size || "",
            }))
        };

        const res = await frappe.call({
            method: 'frappe.client.insert',
            args: { doc: new_so_doc }
        });

        if (res.message && res.message.name) {
            frappe.msgprint({
                title: __('Sales Order Created'),
                message: `SO created: <a href="/app/sales-order/${res.message.name}" target="_blank">${res.message.name}</a>`,
                indicator: 'green'
            });
        } else {
            frappe.msgprint(__('Could not create Sales Order, no response'));
        }
    } catch (error) {
        frappe.msgprint(__('Error creating Sales Order or Customer: ') + error.message);
        console.error(error);
    }
}


async function create_material_requests(frm, bom_items) {
    const items_by_supplier = {};
    let default_warehouse;

    try {
        default_warehouse = await get_default_warehouse(frm.doc.custom_stone_vendor);
    } catch (err) {
        frappe.msgprint(__('Error fetching warehouse: ') + err);
        return;
    }

    // Group BOM items by supplier
    bom_items.forEach(row => {
        if (row.item_code && row.custom_supplier) {
            const supplier = row.custom_supplier;

            if (!items_by_supplier[supplier]) {
                items_by_supplier[supplier] = [];
            }

            items_by_supplier[supplier].push({
                item_code: row.item_code,
                qty: row.qty,
                schedule_date: frappe.datetime.now_date(),
                uom: row.uom,
                warehouse: default_warehouse,
                custom_size: row.custom_size || "",
                description: row.description || "",
                sales_order: frm.doc.name
            });
        }
    });

    const suppliers = Object.keys(items_by_supplier);
    const created_mr_names = [];

    const create_next_mr = function(index) {
        if (index >= suppliers.length) {
            frm.refresh_field("custom_bom_items");

            if (created_mr_names.length) {
                frappe.msgprint({
                    title: __('Material Requests Created'),
                    message: created_mr_names.map(name =>
                        `MR created:<a href="/app/material-request/${name}" target="_blank">${name}</a>`
                    ).join("<br>"),
                    indicator: "blue"
                });
            } else {
                frappe.msgprint(__('No Material Requests were created.'));
            }

            frm.save();
            return;
        }

        const supplier = suppliers[index];
        const doc = {
            doctype: 'Material Request',
            material_request_type: 'Purchase',
            company: frm.doc.custom_stone_vendor,
            transaction_date: frm.doc.transaction_date,
            custom_material_requested_by: frm.doc.company,
            schedule_date: frappe.datetime.now_date(),
            set_warehouse: default_warehouse,
            items: items_by_supplier[supplier],
            sales_order: frm.doc.name
        };

        frappe.call({
            method: 'frappe.client.insert',
            args: { doc },
            callback: function(r) {
                if (r.message && r.message.name) {
                    const mr_name = r.message.name;
                    created_mr_names.push(mr_name);

                    let updated = false;
                    (frm.doc.custom_bom_items || []).forEach(row => {
                        if (row.custom_supplier === supplier && !row.custom_material_request_id) {
                            row.custom_material_request_id = mr_name;
                            updated = true;
                        }
                    });

                    if (updated) {
                        frm.refresh_field("custom_bom_items");
                    }
                }

                create_next_mr(index + 1);
            },
            error: function() {
                frappe.msgprint(__('Error creating Material Request for ') + supplier);
                create_next_mr(index + 1);
            }
        });
    };

    create_next_mr(0);
}

// Create Purchase Orders grouped by supplier from selected SO items
function create_purchase_orders(frm, items, created_mrs = []) {
    const items_by_supplier = {};

    // Helper to get company abbreviation
    const get_company_abbr = (company_name) => {
        if (!company_name) return "UNDEF";
        const known_abbrs = {
            "Bright Blue Jewels": "BBJ",
            "Karlson": "KAR",
            "BBJ Bangkok Ltd": "BBJ-BKK"
        };
        return known_abbrs[company_name] || company_name.split(" ").map(w => w[0]).join("").toUpperCase();
    };

    const company_abbr = get_company_abbr(frm.doc.company);
    const default_warehouse = "Stores - " + company_abbr;

    items.forEach(row => {
        if (row.item_code && row.supplier) {
            if (!items_by_supplier[row.supplier]) {
                items_by_supplier[row.supplier] = [];
            }

            const warehouse = row.warehouse || frm.doc.set_warehouse || default_warehouse;
            const so_item = frm.doc.items.find(i =>
                i.item_code === row.item_code &&
                !i.custom_purchase_order_no &&
                i.qty === row.qty
            );

            items_by_supplier[row.supplier].push({
                item_code: row.item_code,
                qty: row.qty,
                schedule_date: frappe.datetime.now_date(),
                uom: row.uom,
                rate: 1,
                warehouse: warehouse,
                sales_order: frm.doc.name,
                custom_size: row.custom_size || so_item?.custom_size || "",
                description: so_item?.description || ""
            });
        }
    });

    const suppliers = Object.keys(items_by_supplier);
    const created_po_names = [];

    const create_next_po = function(index) {
        if (index >= suppliers.length) {
            frm.refresh_field("items");

            const all_links = [
                ...created_po_names.map(name => ({ type: "PO", name })),
                ...created_mrs.map(name => ({ type: "MR", name }))
            ];

            if (all_links.length) {
                const message = all_links.map(doc =>
                    `PO created:<a href="/app/${doc.type === 'PO' ? 'purchase-order' : 'material-request'}/${doc.name}" target="_blank">
                        ${doc.type} - ${doc.name}
                    </a>`
                ).join('<br>');

                frappe.msgprint({
                    title: __('Documents Created'),
                    message: message,
                    indicator: 'green',
                    wide: true
                });
            } else {
                frappe.msgprint(__('No Purchase Orders or Material Requests were created.'));
            }

            return;
        }

        const supplier = suppliers[index];
        const doc = {
            doctype: 'Purchase Order',
            supplier: supplier,
            schedule_date: frappe.datetime.now_date(),
            items: items_by_supplier[supplier],
            company: frm.doc.company,
            sales_order: frm.doc.name,
            custom_has_our_responsibility_items: frm.doc.custom_has_our_responsibility_items,
            set_warehouse: frm.doc.set_warehouse || default_warehouse
        };

        frappe.call({
            method: 'frappe.client.insert',
            args: { doc },
            callback: function(r) {
                if (r.message && r.message.name) {
                    const po_name = r.message.name;
                    created_po_names.push(po_name);

                    (frm.doc.items || []).forEach(row => {
                        if (row.supplier === supplier && !row.custom_purchase_order_no) {
                            frappe.model.set_value(row.doctype, row.name, "custom_purchase_order_no", po_name);
                        }
                    });

                    frm.save();
                }

                create_next_po(index + 1);
            },
            error: function(err) {
                frappe.msgprint(__('Error creating PO for ') + supplier);
                create_next_po(index + 1);
            }
        });
    };

    create_next_po(0);
}
