    });

    dialog.get_primary_btn().hide();
    dialog.show();
}

function getProgressSteps(itemType) {
    if (itemType === "SKU") {
        return [
            'Sales Order',
            'Purchase Order',
            'Purchase Invoice',
            'Sales Invoice'
        ];
    } else if (itemType === "Stone") {
        return [
            'Sales Order',
            'Material Request',
            'Purchase Invoice',
            'Sales Invoice'
        ];
    }

    return ['Sales Order', 'Purchase Order', 'Purchase Invoice', 'Sales Invoice'];
}

function getCurrentStep(frm, itemType) {
    const salesOrderStatus = frm.doc.docstatus;

    if (itemType === "SKU") {
        const purchaseOrderCreated = frm.doc.custom_purchase_order_created ||
            (frm.doc.items || []).some(item => item.custom_purchase_order_no);

        const purchaseInvoiceCreated = frm.doc.per_billed >= 100;
        const salesInvoiceCreated = frm.doc.per_delivered >= 100 || frm.doc.status === 'Completed';

        if (salesInvoiceCreated) return 3;
        else if (purchaseInvoiceCreated) return 2;
        else if (purchaseOrderCreated) return 1;
        else if (salesOrderStatus >= 1) return 0;

    } else if (itemType === "Stone") {
        const materialRequestCreated = frm.doc.custom_material_request_created ||
            (frm.doc.custom_bom_items || []).some(item => item.custom_material_request_id);

        const purchaseInvoiceCreated = frm.doc.per_billed >= 100;
        const salesInvoiceCreated = frm.doc.per_delivered >= 100 || frm.doc.status === 'Completed';

        if (salesInvoiceCreated) return 3;
        else if (purchaseInvoiceCreated) return 2;
        else if (materialRequestCreated) return 1;
        else if (salesOrderStatus >= 1) return 0;
    }

    return 0;
}

function createTwoLineProgressBars(frm) {
    const INACTIVE = '#b7b6b6';
    const GREEN = '#28a745';
    const isSubmitted = frm.doc.docstatus >= 1;

    const flows = [];

    // Always show STONE
    flows.push({
        label: 'STONE',
        steps: ['Sales Order', 'Stone Request', 'Purchase Invoice', 'Sales Invoice'],
        itemType: 'Stone',
        color: '#4eb9e4'
    });

    // Show SKU only if custom_sales_order_type !== "Stone"
    if (frm.doc.custom_sales_order_type !== "Stone") {
        flows.push({
            label: 'SKU',
            steps: ['Sales Order', 'Purchase Order', 'Purchase Invoice', 'Sales Invoice'],
            itemType: 'SKU',
            color: '#ffa509'
        });
    }

    const getStatus = (itemType) => getCurrentStep(frm, itemType);

    let html = `<div style="width:100%;max-width:1000px;margin:0px;">`;

    flows.forEach(flow => {
        const currStep = getStatus(flow.itemType);
        const STEP_COLOR = isSubmitted ? GREEN : flow.color;
        const badgeColor = flow.color;

        html += `<div style="display:flex;align-items:center;margin-bottom:14px;">`;

        html += `<div style="width:85px;font-size:16px;border-radius: 10px;background: ${badgeColor};color:white;font-weight:600;text-align:center;margin-right:24px;">${flow.label}:</div>`;

        html += `<div style="flex:1;display:flex;align-items:center;">`;

        flow.steps.forEach((step, i) => {
            const isActive = i <= currStep;
            html += `
                <div style="display:flex;flex-direction:column;align-items:center;position:relative;flex:1;">
                    <div style="font-size:15px;font-weight:${isActive ? 500 : 400};color:${isActive ? STEP_COLOR : INACTIVE};margin-top:2px;white-space:nowrap;">${step}</div>
                </div>
            `;
            if (i < flow.steps.length - 1) {
                html += `
                    <div style="display:flex;align-items:center;">
                        <div style="height: 2px;width: 100px;flex:1;background:${i < currStep ? STEP_COLOR : INACTIVE};margin-bottom:0px;margin-left:-2px;margin-right:-2px;z-index:1;border-radius:3px;position:relative;">
                            <div style="
                                position: absolute;
                                right: -6px;
                                top: -6px;
                                width: 0;
                                height: 0;
                                border-top: 7px solid transparent;
                                border-bottom: 7px solid transparent;
                                border-left: 7px solid ${i < currStep ? STEP_COLOR : INACTIVE};
                            "></div>
                        </div>
                    </div>
                `;
            }
        });

        html += `</div></div>`;
    });

    html += `</div>`;
    return html;
}

function show_progress_bar(frm) {
    if (!frm.fields_dict.custom_progress_status) return;

    const finalHTML = createTwoLineProgressBars(frm);
    frm.fields_dict.custom_progress_status.$wrapper.html(finalHTML);
}

