function calculate_difference(frm, cdt, cdn, show_popup = false) {
    let row = locals[cdt][cdn];

    const rate = flt(row.rate);
    const selling_rate = flt(row.selling_rate);
    const amount = flt(row.amount);
    const selling_amount = flt(row.selling_amount);

    const rate_diff = selling_rate - rate;
    const amount_diff = selling_amount - amount;

    frappe.model.set_value(cdt, cdn, "rate_difference", rate_diff);
    frappe.model.set_value(cdt, cdn, "amount_difference", amount_diff);

}

function calculate_all_differences(frm) {
    frm.__rate_warning_shown = false;
    (frm.doc.custom_bom_items || []).forEach(row => {
        const rate = flt(row.rate);
        const selling_rate = flt(row.selling_rate);
        const amount = flt(row.amount);
        const selling_amount = flt(row.selling_amount);

        row.rate_difference = selling_rate - rate;
        row.amount_difference = selling_amount - amount;

    });
    frm.refresh_field("custom_bom_items");
}
function calculate_totals_and_warn(frm) {
    let total_buying = 0;
    let total_selling = 0;

    (frm.doc.custom_bom_items || []).forEach(row => {
        total_buying += flt(row.rate);
        total_selling += flt(row.selling_rate);
    });

    frm.set_value('custom_total_buying_amt', total_buying);
    frm.set_value('custom_total_selling_amt', total_selling);
    frm.set_value('custom_difference_amt', total_selling - total_buying);

    if (total_buying > total_selling) {
        frappe.msgprint({
            title: __('Warning'),
            indicator: 'red',
            message: __('Buying Amount is higher than the Selling amount. Please negotiate once again.')
        });
    }
}

