frappe.ui.form.on('Customer Worksheet', {
    setup: function(frm, cdt, cdn){
        let row = locals[cdt][cdn];
        frappe.call({
            method: "get_country_of_origin",
            args: { gemstone: row.custom_gemstone },
            callback: function (r) {
                if (r.data) {
                    const allowed_countries = r.data.map(entry => entry[1]);
                    let unique_countries = [...new Set(allowed_countries)];
                    cur_frm.fields_dict.bom_items.grid.update_docfield_property(
                        'custom_country_of_origin', 'options', unique_countries
                    );
                }
            }
        });
    },

    onload: function(frm) {
        // BOM filter binding
        frm.set_query('bom_id', () => {
            const item_codes = (frm.doc.customer_worksheet_items || []).map(row => row.item_code);
            if (!item_codes.length) return {};
            return {
                filters: {
                    item: ['in', item_codes],
                    is_active: 1,
                    is_default: 1
                }
            };
        });
        update_total_items(frm); // summary count
    },
    onload_post_render: function(frm) {
        calculate_total_qty(frm);
    },

    refresh: function(frm) {
        update_description(frm);
        toggle_bom_total_html(frm);
    },

    validate: function(frm) {
        update_total_items(frm);
        calculate_total_qty(frm);
    },

    item_group: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (["Stone", "Pearl", "Bead"].includes(row.item_group)) {
            frappe.model.set_value(cdt, cdn, 'default_stock_uom', 'Carat');
        } else if (row.item_group === "Metal") {
            frappe.model.set_value(cdt, cdn, 'default_stock_uom', 'Gram');
        } else {
            frappe.model.set_value(cdt, cdn, 'default_stock_uom', 'Piece');
        }
    },

    bom_id: function(frm) {
        toggle_bom_total_html(frm);
        const bomId = frm.doc.bom_id;

        if (!bomId) {
            frm.doc.customer_bom_items = (frm.doc.customer_bom_items || []).filter(row => row.bom_no !== frm.__last_bom_id);
            frm.refresh_field("customer_bom_items");
            return;
        }
        frm.__last_bom_id = bomId;
        frappe.call({
            method: 'frappe.client.get',
            args: { doctype: 'BOM', name: bomId },
            callback: function(r) {
                if (!r.message || !r.message.items) return;

                frm.clear_table('customer_bom_items');
                r.message.items.forEach(function(item) {
                    let row = frm.add_child('customer_bom_items');
                    // copy each property via loop for brevity, or directly as in your code
                    Object.assign(row, {
                        item_code: item.item_code,
                        item_name: item.item_name,
                        bom_no: bomId,
                        qty: item.qty || 1,
                        uom: item.uom,
                        custom_with_jback: item.custom_with_jback,
                        rate: item.rate || 0,
                        amount: item.amount || 0,
                        description: item.description,
                        item_group: item.custom_item_group || '',
                        custom_item_group: item.custom_item_group,
                        custom_selling_rate: item.custom_selling_rate || '',
                        custom_selling_amount: item.custom_selling_amount || '',
                        custom_gemstone: item.custom_gemstone,
