function open_split_po_dialog(frm) {
    const supplier = frm.doc.supplier;

    const items_data = frm.doc.items.map(item => ({
        item_code: item.item_code || '',
        qty: item.qty || 0,
        selected_qty: 0,
        balance_qty: item.qty || 0
    }));

    const dialog = new frappe.ui.Dialog({
        title: 'Select Items for PO',
        size: 'large',
        fields: [
            {
                label: 'Supplier',
                fieldname: 'supplier',
                fieldtype: 'Link',
                options: 'Supplier',
                reqd: 1,
                default: supplier
            },
            {
                label: 'Items',
                fieldname: 'items_table',
                fieldtype: 'Table',
                cannot_add_rows: true,
                in_place_edit: true,
                fields: [{label: 'Item Code',fieldname: 'item_code',fieldtype: 'Data',read_only: 1,in_list_view: 1},
                {label: 'Total Qty',fieldname: 'qty',fieldtype: 'Float',read_only: 1,in_list_view: 1},
                {label: 'Selected Qty',fieldname: 'selected_qty',fieldtype: 'Float',in_list_view: 1},
                {label: 'Balance Qty',fieldname: 'balance_qty',fieldtype: 'Float',read_only: 1,in_list_view: 1}]
            },
    {
        fieldtype: 'HTML',
        options: '<div style="margin: 10px 0; font-weight: bold;text-align:center;">Select items to split by entering quantities in the <u>Selected Qty</u> fields.</div>'
    }
        ],
        primary_action_label: 'Proceed',
        primary_action(values) {
            const selected_items = values.items_table.filter(row => row.selected_qty > 0);

            if (!selected_items.length) {
                frappe.msgprint(__('Please enter selected quantity for at least one item.'));
                return;
            }
            selected_items.forEach(dialog_item => {
                const original_row = frm.doc.items.find(item => item.item_code === dialog_item.item_code);
                if (original_row) {
                    original_row.qty = dialog_item.balance_qty;
                }
            });            
            frm.dirty();
            frm.save();
            frm.refresh_field('items');
            
            frappe.call({
            method: 'frappe.client.insert',
            args: {
                doc: {
                    doctype: 'Purchase Order',
                    supplier: values.supplier,
                    schedule_date: frm.doc.schedule_date,
                    transaction_date: frappe.datetime.get_today(),
                    set_warehouse: frm.doc.set_warehouse,
                    items: selected_items.map(item => {
                        const original_item = frm.doc.items.find(orig => orig.item_code === item.item_code);
                        return {
                            item_code: item.item_code,
                            qty: item.selected_qty,
                            schedule_date: frm.doc.schedule_date,
                            po_reference: frm.doc.name,
                            sales_order: original_item?.sales_order || frm.doc.sales_order,
                            uom: original_item?.uom,
                            rate: original_item?.rate,
                            stock_uom: original_item?.stock_uom,
                            description: original_item?.description
                        };
                    }),
                }
            },
            callback: (r) => {
                if (!r.exc) {
                    const message = `New Purchase Order <a href="/app/purchase-order/${r.message.name}">${r.message.name}</a> created.`;
            
                    const custom_dialog = new frappe.ui.Dialog({
                        title: "Success",
                        fields: [
                            {
                                fieldtype: "HTML",
                                options: `<div style="padding: 10px;">${message}</div>`
                            }
                        ],
                        primary_action_label: "Close",
                        primary_action() {
                            custom_dialog.hide();
                        }
                    });
            
                    custom_dialog.show();
            
                    setTimeout(() => {
                        custom_dialog.hide();
                    }, 30000);
            
                    dialog.hide();
                }
            }

        });

        }
    });

    dialog.show();

    dialog.fields_dict.items_table.df.data = items_data;
    dialog.fields_dict.items_table.grid.refresh();
    
    const grid = dialog.fields_dict['items_table'].grid;

    grid.wrapper.on('change', 'input[data-fieldname="selected_qty"]', function (e) {
    const row_idx = $(this).closest('.grid-row').data('idx') - 1;
    const row = dialog.fields_dict.items_table.df.data[row_idx];

    const total_qty = parseFloat(row.qty) || 0;
    const raw_val = $(this).val().replace(/,/g, ''); 
    const selected_qty = parseFloat(raw_val) || 0;

    if (selected_qty > total_qty) {
        frappe.msgprint(__('Selected Qty cannot be greater than Total Qty.'));
        row.selected_qty = 0;
        row.balance_qty = total_qty;
        dialog.fields_dict.items_table.grid.refresh();
        return;
    }

    row.balance_qty = total_qty - selected_qty;
    dialog.fields_dict.items_table.grid.refresh();
});
}



// ===========Stone Treatment=============

function bindPopupToTreatmentField(frm) {
    const $table = frm.fields_dict.custom_bom_items.grid.wrapper;
    $table.off('click', "[data-fieldname='custom_stone_treatment_list']");
    $table.on('click', "[data-fieldname='custom_stone_treatment_list']", function (e) {
        e.stopPropagation();
        const grid_row = $(this).closest('.grid-row');
        const row_name = grid_row.attr('data-name');
        const grid = frm.fields_dict.custom_bom_items.grid;
        const row = grid.grid_rows_by_docname[row_name].doc;
        if ($(this).data('popup-opened')) return;
        $(this).data('popup-opened', true);
        const all_rows = frm.doc.custom_bom_items || [];
        let start_index = all_rows.findIndex(r => r.name === row.name);
        
        function openTreatmentDialog(index) {
            if (index >= all_rows.length) return;
            const current_row = all_rows[index];
            if (current_row.item_group !== "Stone") return;
            
            let currentDialogSelected = new Set();
            let searchTimeout;
            
            const dialog = new frappe.ui.form.MultiSelectDialog({
                doctype: 'Stone Treatment',
                target: frm,
                setters: {},
                add_filters_group: 0,
                allow_multiple: true,
                action: function (selected_values) {
                    const treatment_list = Array.from(currentDialogSelected).join(', ');
                    frappe.model.set_value(current_row.doctype, current_row.name, 'custom_stone_treatment_list', treatment_list);
                    this.dialog.hide();
                    setTimeout(() => openTreatmentDialog(index + 1), 400);
                },
                primary_action_label: 'Insert',
                get_query: () => ({ filters: {} }),
                action_on_cancel: function () {}
            });
            
            const waitForDialog = setInterval(() => {
                if (dialog.dialog && dialog.dialog.$wrapper && dialog.dialog.$wrapper.is(':visible')) {
                    clearInterval(waitForDialog);
                    
                    dialog.dialog.$body.find('.custom-header').remove();
                    const display_index = index + 1;
                    const item_code = current_row.item_code || '-';
                    const item_name = current_row.item_name || '-';
                    const stone_pieces = current_row.custom_stone_pieces || '0';
                    
                    const header_html = `
                        <div class="custom-header" style="padding: 10px; background-color: #f1f5f9; border-bottom: 1px solid #ccc; margin-bottom: 10px;">
                            <strong>Row-${display_index}:</strong> ${item_code}: ${item_name} – ${stone_pieces} Stone Pieces
                            <div id="selected-treatments-${index}" style="margin-top: 5px;">
                                <span style="color: black; font-weight: 500;">Selected:</span> 
                                <span style="color: green; font-weight: 500;">None</span>
                            </div>
                        </div>
                    `;
                    dialog.dialog.$body.prepend($(header_html));
                    
                    const getCheckboxLabel = ($checkbox) => {
                        return $checkbox.attr('data-item-name') || 
                               $checkbox.closest('.list-row-check').attr('data-item-name') ||
                               $checkbox.parents('[data-item-name]').first().attr('data-item-name') ||
                               $checkbox.next().text().trim();
                    };
                    
                    const restoreSelections = () => {
                        dialog.dialog.$body.find('input[type="checkbox"]').each(function() {
                            const label = getCheckboxLabel($(this));
                            if (label && currentDialogSelected.has(label)) {
                                $(this).prop('checked', true);
                            }
                        });
                    };
                    
                    const updateLiveSelection = () => {
                        dialog.dialog.$body.find('input[type="checkbox"]:checked').each(function() {
                            const label = getCheckboxLabel($(this));
                            if (label && label !== 'Name' && label !== '') {
                                currentDialogSelected.add(label);
                            }
                        });
                        
                        dialog.dialog.$body.find('input[type="checkbox"]:not(:checked)').each(function() {
                            const label = getCheckboxLabel($(this));
                            if (label && label !== 'Name' && label !== '') {
                                currentDialogSelected.delete(label);
                            }
                        });
                        
                        const selectedText = currentDialogSelected.size > 0 ? Array.from(currentDialogSelected).join(', ') : 'None';
                        $(`#selected-treatments-${index}`).html(`
                            <span style="color: black; font-weight: 500;">Selected:</span> 
                            <span style="color: green; font-weight: 500;">${selectedText}</span>
                        `);
                    };
                    
                    dialog.dialog.$body.off('click.liveselect change.liveselect');
                    dialog.dialog.$body.on('click.liveselect change.liveselect', 'input[type="checkbox"], .list-row-check', function() {
                        setTimeout(updateLiveSelection, 50);
                    });
                    
                    const observer = new MutationObserver(function(mutations) {
                        let shouldUpdate = mutations.some(mutation => 
                            mutation.type === 'childList' && (mutation.addedNodes.length > 0 || mutation.removedNodes.length > 0)
                        );
                        
                        if (shouldUpdate) {
                            clearTimeout(searchTimeout);
                            searchTimeout = setTimeout(() => {
                                restoreSelections();
                                updateLiveSelection();
                            }, 200);
                        }
                    });
                    
                    observer.observe(dialog.dialog.$body[0], { childList: true, subtree: true });
                    
                    setTimeout(() => {
                        const searchInput = dialog.dialog.$body.find('input[type="text"], input[data-fieldtype="Data"]').first();
                        if (searchInput.length) {
                            searchInput.on('input keyup', function() {
                                clearTimeout(searchTimeout);
                                searchTimeout = setTimeout(() => {
                                    restoreSelections();
                                    updateLiveSelection();
                                }, 500);
                            });
                        }
                    }, 1000);
                    
                    setTimeout(updateLiveSelection, 500);
                    setTimeout(updateLiveSelection, 1000);
                    
                    dialog.dialog.onhide = function() {
                        observer.disconnect();
                        $(this).data('popup-opened', false);
                    };
                }
            }, 50);
        }
        
        openTreatmentDialog(start_index);
    });
}

