/**
 * Add black button style (once) and ensure all relevant buttons styled.
 * Also binds/ensures "Duplicate BOM" dialog only once.
 */
function styleBlackButtonsAndInitDuplication(frm) {
    // Only add style once
    if (!$('style#custom-black-buttons').length) {
        $('head').append(`
            <style id="custom-black-buttons">
                .black-btn {
                    background-color: #000 !important;
                    color: #fff !important;
                    border: none !important;
                    border-radius: 6px;
                    padding: 6px 10px !important;
                    font-weight: 600;
                    box-shadow: none;
                    transition: background-color 0.2s ease;
                }
                .black-btn:hover {
                    background-color: #222 !important;
                }
            </style>
        `);
    }

    // Which buttons to style?
    const styledButtonLabels = [
        "Create BOM", "Search BOM", "Fetch Item without BOM", "Search", "Create and Insert",
        "Clear", "Clear Search", "Update BOM Changes", "Update BOM", "Duplicate BOM"
    ];

    // DRY styling & binding
    setTimeout(() => {
        $('button').each(function () {
            const $btn = $(this);
            const text = $btn.text().trim();
            if (styledButtonLabels.includes(text)) $btn.addClass('black-btn');
        });
        // Bind Duplicate BOM
        ensureDuplicateBomFunctionality(frm);
    }, 300);
}

/**
 * Finds the "Duplicate BOM" button and ensures it opens a unique-select dialog for duplication.
 * Unbinds/rebinds to prevent stacking events.
 */
function ensureDuplicateBomFunctionality(frm, retry = 0) {
    const $dupBtn = $('button').filter(function () {
        return $(this).text().trim().toLowerCase() === 'duplicate bom';
    });

    if ($dupBtn.length) {
        $dupBtn.addClass('black-btn').show().off('click').on('click', () =>
            showDuplicateBomDialog(frm)
        );
    } else if (retry < 3) {
        setTimeout(() => ensureDuplicateBomFunctionality(frm, retry + 1), 300);
    }
}

/**
 * Opens dialog to select worksheet item to duplicate BOM. 
 * Handles all side effects and creation.
 */
function showDuplicateBomDialog(frm) {
    const items = frm.doc.customer_worksheet_items || [];
    if (!items.length) {
        frappe.msgprint("No items found in the worksheet.");
        return;
    }

    // List all as radio options.
    const htmlOptions = items.map(row => `
        <div style="margin-bottom: 10px;">
            <label style="display: flex; align-items: start; gap: 8px;">
                <input type="radio" name="item_select" value="${row.name}" style="margin-top: 4px;">
                <span style="flex: 1; word-break: break-word;">
                    ${row.item_code || ""} : ${row.item_name || ""} (${row.item_group || ""})
                </span>
            </label>
        </div>
    `).join('');

    const dialog = new frappe.ui.Dialog({
        title: "Select One to Duplicate",
        size: "small",
        fields: [
            {
                fieldtype: 'HTML',
                fieldname: 'radio_html',
                options: `<div style="max-height: 300px; overflow-y: auto;">${htmlOptions}</div>`
            }
        ],
        primary_action_label: "Insert",
        primary_action: async () => {
            const selectedRowName = dialog.$wrapper.find('input[name="item_select"]:checked').val();
            if (!selectedRowName) return frappe.msgprint("Please select one item.");
            const row = items.find(r => r.name === selectedRowName);
            if (!row || !row.default_bom) {
                frappe.msgprint("No default BOM found in selected item.");
                return;
            }
            openBOMDuplicationConfirm(frm, row, dialog);
        }
    });
    dialog.show();
}

/**
 * Opens the confirmation/details dialog for BOM duplication.
 * Handles the server-side item creation + client table insertion.
 */
async function openBOMDuplicationConfirm(frm, row, prevDialog) {
    const confirmDialog = new frappe.ui.Dialog({
        title: 'Confirm BOM Duplication',
        fields: [
            { fieldtype: 'Section Break', label: 'Existing Item Details' },
            { fieldtype: 'HTML', fieldname: 'existing_info', options: `
                <div style="margin-bottom: 10px;">
                    <div><b>Item Name:</b> ${row.item_name || ''}</div>
                    <div><b>Vendor Product ID:</b> ${row.custom_vendor_product_id || ''}</div>
                </div>
            `},
            { fieldtype: 'Section Break', label: 'New Item Details' },
            { fieldtype: 'Data', label: 'New Item Name', fieldname: 'new_item', reqd: 1 },
            { fieldtype: 'Data', label: 'Vendor Product ID', fieldname: 'new_vendor_product_id', reqd: 1 }
        ],
        primary_action_label: 'Duplicate',
        primary_action: async (values) => {
            const { new_item, new_vendor_product_id } = values;
            await duplicateItemAndBOM(frm, row, new_item, new_vendor_product_id, confirmDialog, prevDialog);
        }
    });
    confirmDialog.show();
}

/**
 * Handles:
 * 1. Creating new item (auto-increment code by group prefix)
 * 2. Adding that new item to worksheet table
 * 3. Copying BOM items to child table and filling BOM field
 */
async function duplicateItemAndBOM(frm, row, new_item_name, new_vendor_id, confirmDialog, initialDialog) {
    const { item_code, item_group, default_bom } = row;

    try {
        frappe.dom.freeze("Creating new item...");

        // Fetch existing item (for field defaults)
        const { message: existing_item = {} } = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Item",
                name: item_code
            }
        });

        // Unique item_code: three-letter group prefix + increment.
        let prefix = (existing_item.item_group || "ITEM").substring(0, 3).toUpperCase();
        const { message: exist_items } = await frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Item",
                filters: [["item_code", "like", `${prefix}-%`]],
                fields: ["item_code"],
                limit_page_length: 1000
            }
        });
        let max_number = 0;
        (exist_items || []).forEach(d => {
            const m = d.item_code.match(new RegExp(`^${prefix}-(\\d+)$`));
            if (m) max_number = Math.max(max_number, parseInt(m[1]));
        });
        let new_item_code = `${prefix}-${String(max_number + 1).padStart(4, '0')}`;

        // Insert new item.
        await frappe.call({
            method: "frappe.client.insert",
            args: {
                doc: {
                    doctype: "Item",
                    item_code: new_item_code,
                    item_name: new_item_name,
                    item_group: existing_item.item_group,
                    custom_vendor_product_id: new_vendor_id,
                    description: existing_item.description,
                    stock_uom: existing_item.stock_uom,
                    custom_customer_sku: existing_item.custom_customer_sku,
                    custom_metal_group: existing_item.custom_metal_group,
                    custom_material_id: existing_item.custom_material_id,
                    is_stock_item: existing_item.is_stock_item,
                    gst_hsn_code: existing_item.gst_hsn_code,
                    sales_uom: existing_item.sales_uom,
                    image: existing_item.image,
                    purchase_uom: existing_item.purchase_uom
                }
            }
        });

        // Add to worksheet
        let new_row = frm.add_child("customer_worksheet_items");
        new_row.item_code = new_item_code;
        new_row.item_name = new_item_name;
        new_row.item_group = existing_item.item_group;
        new_row.custom_vendor_product_id = new_vendor_id;
        new_row.default_bom = default_bom;
        frm.refresh_field("customer_worksheet_items");

        frappe.dom.unfreeze();
        frappe.msgprint(`New item <a href="/app/item/${new_item_code}" target="_blank"><b>${new_item_code}</b></a> has been created.`);

        // Now copy the BOM items, clear BOM table first
        frappe.dom.freeze("Loading BOM items...");
        const { message: bom } = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "BOM",
                name: default_bom
            }
        });

        frm.clear_table('bom_items');
        (bom.items || []).forEach(item => {
            let child = frm.add_child('bom_items');
            Object.assign(child, {
                item_code: item.item_code,
                item_name: item.item_name,
                custom_item_group: item.custom_item_group,
                qty: item.qty,
                uom: item.uom,
                rate: item.rate || 0.0,
                amount: item.amount || 0,
                custom_selling_rate: item.custom_selling_rate || '',
                custom_selling_amount: item.custom_selling_amount || '',
                custom_gemstone: item.custom_gemstone,
                description: item.description,
                custom_stone_treatment_list: item.custom_stone_treatment_list,
                custom_merch_color__attribute: item.custom_merch_color__attribute,
                custom_country_of_origin: item.custom_country_of_origin,
                custom_grade: item.custom_grade,
                custom_stone_pieces: item.custom_stone_pieces,
                custom_avg_carat_weight: item.custom_avg_carat_weight,
                custom_sku_carat_weight: item.custom_sku_carat_weight,
                custom_cut: item.custom_cut,
                custom_setting_type: item.custom_setting_type,
                custom_metal_weight: item.custom_metal_weight,
                custom_sku_metal_weight: item.custom_sku_metal_weight,
                custom_metal_group: item.custom_metal_group,
                custom_sku_weight: item.custom_sku_weight,
                custom_ext_qty_required: item.custom_ext_qty_required,
                custom_oh: item.custom_oh,
                custom_net_balance_required: item.custom_net_balance_required,
                custom_our_responsibility: item.custom_our_responsibility,
                custom_with_jback: item.custom_with_jback
            });
        });
        frm.refresh_field('bom_items');
        confirmDialog.hide();
        if (initialDialog) initialDialog.hide();
        frm.set_value('finished_goods_item', new_item_code);

        frappe.dom.unfreeze();
        frappe.msgprint(`Previous Item BOM <b>${default_bom}</b> has been fetched.`);
    } catch (err) {
        frappe.dom.unfreeze();
        console.error("Error:", err);
        frappe.msgprint("Error during item creation or BOM duplication.");
    }
}

