 add_items: function (frm) {
    frappe.call({
        method: "get_items_with_draft_sales_order",
        args: {
            doctype: "Item",
            filters: { custom_vendor_product_id: ["!=", ""] },
            fields: ["name", "item_name", "custom_vendor_product_id", "item_group", "custom_customer_sku", "description"],
            limit_page_length: 100000
        },
        callback: function (r) {
            if (!r.message || r.message.length === 0) {
                frappe.msgprint("No Vendor IDs found.");
                return;
            }

            const all_items = r.message;
            const seen_ids = new Set();
            const unique_items = all_items.filter(item => {
                if (seen_ids.has(item.custom_vendor_product_id)) return false;
                seen_ids.add(item.custom_vendor_product_id);
                return true;
            });

            const highlightMatch = (text, query) => {
                if (!query) return text;
                const escaped = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                const regex = new RegExp(`(${escaped})`, 'gi');
                return text.replace(regex, '<span style="background-color: yellow;">$1</span>');
            };

            const generate_table_rows = (items, query = "") =>
                items.map(item => `
                    <tr class="vendor-row">
                        <td style="text-align:center;"><input type="checkbox" class="vendor-checkbox" data-id="${item.custom_vendor_product_id}" /></td>
                        <td><b>${highlightMatch(item.custom_vendor_product_id, query)}</b></td>
                        <td>${highlightMatch(item.item_name, query)}</td>
                    </tr>
                `).join("");

            const html = `
                <div style="margin-bottom: 12px;">
                    <input type="text" id="vendor-search" placeholder="Search Here"
                        style="flex: 1; padding: 6px 10px; margin-right: 12px; border: 1px solid #ccc; border-radius: 4px;">
                    <button class="btn btn-secondary btn-md" id="vendor-clear-btn">Clear</button>
                </div>
                <div style="display: flex; justify-content: flex-end; gap: 20px; margin-bottom: 12px;">
                  
                    <span><b>Inserted:</b> <span id="inserted-count" style="color: green;">0</span></span>
                </div>
                <div style="max-height: 400px; overflow-y: auto; border: 1px solid #ddd; border-radius: 6px;">
                    <table style="width: 100%;">
                        <thead>
                            <tr style="background-color: #f9fafb;">
                                <th style="width: 60px;">Select</th>
                                <th style="width:200px;">Vendor Product ID</th>
                                <th>Item Name</th>
                            </tr>
                        </thead>
                        <tbody id="vendor-table-body"></tbody>
                    </table>
                </div>
            `;

            const d = new frappe.ui.Dialog({
                title: 'Select Vendor Product IDs to Add',
                fields: [{ fieldtype: 'HTML', fieldname: 'vendor_table', options: html }],
                size: 'large',
                primary_action_label: 'Insert',
                primary_action() {
                    const selected_ids = Array.from(d.$wrapper.find('.vendor-checkbox:checked')).map(cb => $(cb).data('id'));
                    if (selected_ids.length === 0) {
                        frappe.msgprint("Please select at least one Vendor ID.");
                        return;
                    }

                    let inserted_count = 0;
                    all_items.filter(item => selected_ids.includes(item.custom_vendor_product_id)).forEach(item => {
                        const row = frm.add_child('items_details', {
                            item_code: item.name.trim(),
                            item_name: item.item_name,
                            vendor_product_id: item.custom_vendor_product_id,
                            item_group: item.item_group,
                            status: "Fetched",
                            customer_sku: item.custom_customer_sku || "",
                            description: item.description || ""
                        });
                        inserted_count++;
                        fetch_item_info(frm, row.doctype, row.name);
                    });

                    frm.refresh_field('items_details');
                    d.$wrapper.find('#inserted-count').text(inserted_count);
                    d.$wrapper.find('#vendor-search').val("");
                    d.$wrapper.find('#vendor-table-body').empty();
                    // d.$wrapper.find('#selected-count').text("0");
                    // d.$wrapper.find('#total-count').html(`<b>Total IDs:</b> 0`);
                }
            });

            d.show();

            const wrapper = d.$wrapper;
            const searchInput = wrapper.find('#vendor-search');
            const tableBody = wrapper.find('#vendor-table-body');

            wrapper.on('change', '.vendor-checkbox', function () {
                wrapper.find('#selected-count').text(wrapper.find('.vendor-checkbox:checked').length);
            });

            wrapper.on('click', '#vendor-clear-btn', function () {
                searchInput.val("");
                tableBody.empty();
                wrapper.find('#selected-count').text("0");
                wrapper.find('#total-count').html(`<b>Total IDs:</b> 0`);
                wrapper.find('#inserted-count').text("0");
            });

            searchInput.on('keyup', function () {
                const query = searchInput.val().trim().toLowerCase();
                const filtered = unique_items.filter(item => {
                    const combined = `${item.custom_vendor_product_id} ${item.item_name}`.toLowerCase();
                    return combined.includes(query);
                });

                if (filtered.length === 0) {
                tableBody.html(`
                    <tr>
                        <td colspan="3" style="text-align: center; color: red; padding: 12px;">
                            No Sales Order is created for this item.
                        </td>
                    </tr>
                `);
            } else {
                tableBody.html(generate_table_rows(filtered, query));
            }

                wrapper.find('#selected-count').text("0");
                // wrapper.find('#total-count').html(`<b>Total IDs:</b> ${filtered.length}`);
                // wrapper.find('#inserted-count').text("0");
            });
        }
    });
}
