            });

            searchInput.on('keyup', function () {
                render_table(searchInput.val().trim());
            });
            
            wrapper.find('#with-po-filter').on('change', function () {
                render_table(searchInput.val().trim());
            });

            searchInput.on('keyup', function () {
                const query = searchInput.val().trim();
                render_table(query);
            });
        }
    });
}

