function update_item_data_and_dependencies(frm) {
    const groupedItems = {};

    // Step 1: Group rows by item_code
    frm.doc.items_details.forEach(row => {
        if (!row.item_code) return;
        if (!groupedItems[row.item_code]) {
            groupedItems[row.item_code] = [];
        }
        groupedItems[row.item_code].push(row);
    });

    // Step 2: For each group (unique item_code)
    Object.keys(groupedItems).forEach(item_code => {
        const rows = groupedItems[item_code];

        // Pick first row that has any meaningful update
        const sourceRow = rows.find(r => r.item_name || r.description || r.customer_sku);
        if (!sourceRow) return;

        // Step 3: Copy data to all rows with same item_code
        rows.forEach(row => {
            row.item_name = sourceRow.item_name;
            row.description = sourceRow.description;
            row.customer_sku = sourceRow.customer_sku;
        });

        // Step 4: Update Item master
        frappe.call({
            method: "frappe.client.set_value",
            args: {
                doctype: "Item",
                name: item_code,
                fieldname: {
                    ...(sourceRow.customer_sku ? { custom_customer_sku: sourceRow.customer_sku } : {}),
                    ...(sourceRow.item_name ? { item_name: sourceRow.item_name } : {}),
                    ...(sourceRow.description ? { description: sourceRow.description } : {})
                }
            },
            callback: function () {
                console.log(`Item ${item_code} updated.`);

                // Step 5: Update BOM if available
                if (sourceRow.bom) {
                    frappe.call({
                        method: "frappe.client.get",
                        args: {
                            doctype: "BOM",
                            name: sourceRow.bom
                        },
                        callback: function (bomRes) {
                            const bom = bomRes.message;
                            bom.items.forEach(i => {
                                if (i.item_code === item_code) {
                                    i.item_name = sourceRow.item_name;
                                    i.description = sourceRow.description;
                                }
                            });

                            frappe.call({
                                method: "frappe.client.save",
                                args: { doc: bom },
                                callback: function () {
                                    console.log(`BOM ${sourceRow.bom} synced with Item master values.`);
                                }
                            });
                        }
                    });
                }

                // Step 6: Update Purchase Order if available
                if (sourceRow.purchase_order) {
                    frappe.call({
                        method: "frappe.client.get",
                        args: {
                            doctype: "Purchase Order",
                            name: sourceRow.purchase_order
                        },
                        callback: function (poRes) {
                            const po = poRes.message;
                            let updated = false;

                            po.items.forEach(po_item => {
                                if (po_item.item_code === item_code) {
                                    po_item.item_name = sourceRow.item_name;
                                    po_item.description = sourceRow.description;
                                    updated = true;
                                }
                            });

                            if (updated) {
                                frappe.call({
                                    method: "frappe.client.save",
                                    args: { doc: po },
                                    callback: function () {
                                        console.log(`PO ${sourceRow.purchase_order} updated with latest item details.`);
                                    }
                                });
                            }
                        }
                    });
                }
            }
        });
    });

    // Step 7: Refresh the field to reflect changes in UI
    frm.refresh_field("items_details");
}

// ========== Fetch Additional Item Info ==========
function fetch_item_info(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    if (!row.item_code) return;

    frappe.call({
        method: "get_item_related_info",
        args: { item_code: row.item_code },
        callback: function (r) {
            if (r.message) {
                const info = r.message;

                if (info.sales_orders && info.sales_orders.length > 0) {

                    const so = info.sales_orders[0];
                    row.vendor_product_id = so.custom_vendor_product_id;
                    row.sales_order = so.sales_order;
                    row.order_type = so.custom_sales_order_type;
                    row.delivery_date = so.delivery_date;
                    row.sales_order_status = so.status;
                    row.purchase_order = info.purchase_order;
                    row.purchase_order_status = info.purchase_order_status;
                    row.bom = info.bom;
                    row.bom_status = info.bom_status;
                    row.item_group = so.item_group || "";
                    row.qty = so.qty;
                    row.size = so.custom_size;
                    row.rate = so.rate;
                    row.amount = so.amount;
                    row.customer_po_id = so.po_no;
                    row.customer_po_date = so.po_date;
                    
                    frm.refresh_field("items_details");

                }
            }
        }
    });
}

