function sort_items_by_size(frm) {
    if (!frm.doc.items_details || frm.doc.items_details.length === 0) return;

    let sorted = frm.doc.items_details.sort((a, b) => {
        if ((a.item_code || "") < (b.item_code || "")) return -1;
        if ((a.item_code || "") > (b.item_code || "")) return 1;

        return (a.size || 0) - (b.size || 0);
    });

    frm.clear_table('items_details');
    sorted.forEach(row => {
        frm.add_child('items_details', row);
    });

    frm.refresh_field('items_details');
}


