function calculate_custom_bom_totals(frm) {
    let with_resp_total = 0;
    let without_resp_total = 0;

    (frm.doc.custom_bom_items || []).forEach(function(row) {
        if (row.custom_our_responsibility) {
            with_resp_total += row.custom_selling_amount || 0;
        } else {
            without_resp_total += row.custom_selling_amount || 0;
        }
    });

    frm.set_value("custom_bom_selling_amt_with_resp", with_resp_total);
    frm.set_value("custom_bom_selling_amt_without_resp", without_resp_total);
}

function calculate_custom_po_qty(frm) {
    if (!frm.doc.total_qty) return;

    frm.doc.custom_bom_items.forEach(row => {
        if (row.qty) {
            row.custom_purchase_order_qty = row.qty * frm.doc.total_qty;
        }
    });

    frm.refresh_field('custom_bom_items');
}

