function open_doc_popup(frm, doc_type, display_title) {
    let customer_po = frm.doc.customer_purchase_order;

    if (!customer_po) {
        frappe.msgprint("Please enter Customer Purchase Order before proceeding.");
        return;
    }

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: doc_type,
            filters: {
                po_no: customer_po  // filtering by customer_purchase_order
            },
            fields: ['name', 'customer', 'po_no'],
            limit_page_length: 1000
        },
        callback: function(r) {
            if (r.message && r.message.length) {
                show_doc_selection_dialog(frm, r.message, doc_type, display_title);
            } else {
                frappe.msgprint(`No ${doc_type}s found for Customer PO: ${customer_po}.`);
            }
        }
    });
}


function show_doc_selection_dialog(frm, doc_list, doc_type, display_title) {
    let d = new frappe.ui.Dialog({
        title: `Select ${display_title}`,
        fields: [
            {
                fieldtype: 'HTML',
                fieldname: 'doc_html',
                options: ''
            }
        ],
        primary_action_label: 'Insert',
        primary_action() {
            let selected_docs = [];
            $(d.get_field('doc_html').wrapper).find('input:checked').each(function () {
                selected_docs.push($(this).val());
            });

            if (selected_docs.length) {
                fetch_and_insert_doc_items(frm, selected_docs, doc_type);
                d.hide();
            } else {
                frappe.msgprint('Please select at least one.');
            }
        }
    });

    let html = `<table class="table table-bordered">
        <thead><tr><th>Select</th><th>${doc_type}</th><th>Customer</th><th>PO No</th></tr></thead><tbody>`;
    doc_list.forEach(doc => {
        html += `<tr>
            <td><input type="checkbox" value="${doc.name}"></td>
            <td style="width:30%;">${doc.name}</td>
            <td>${doc.customer}</td>
            <td>${doc.po_no}</td>
        </tr>`;
    });
    html += '</tbody></table>';

    d.fields_dict.doc_html.$wrapper.html(html);
    d.show();
}

function fetch_and_insert_doc_items(frm, selected_docs, doc_type) {
    if (!selected_docs.length) return;

    frm.clear_table("items"); 
    let total_items = [];

    const fetchNext = (index) => {
        if (index >= selected_docs.length) {
            frm.refresh_field("items");
            frm.set_value('item_count', total_items.length);
            calculate_total_net_weight(frm);
            return;
        }

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: doc_type,
                name: selected_docs[index]
            },
            callback: function(r) {
                if (r.message) {
                    let items = r.message.items || [];

                    items.forEach(function(item) {
                        let child = frm.add_child("items");
                        child.item_code = item.item_code;
                        child.item_name = item.item_name;
                        child.qty = item.qty;
                        child.uom = item.uom; 
                        child.weight_uom ="Kilogram";
                        total_items.push(child);
                    });
                }

                fetchNext(index + 1); 
            }
        });
    };

    fetchNext(0);
}


