function calculate_volume(frm) {
    if (frm.doc.length && frm.doc.width && frm.doc.height) {
        frm.set_value('volume', (frm.doc.length * frm.doc.width * frm.doc.height) / 1000000);
    } else {
        frm.set_value('volume', 0);
    }
}

function calculate_gross_weight(frm) {
    if (frm.doc.net_weight && frm.doc.weight) {
        frm.set_value('gross_weight', frm.doc.net_weight * frm.doc.weight);
    } else {
        frm.set_value('gross_weight', 0);
    }
}

function set_default_weight_uom(frm) {
    if (frm.doc.items) {
        frm.doc.items.forEach(function(row) {
            if (!row.weight_uom) {
                row.weight_uom = 'Kilogram';
            }
        });
        frm.refresh_field('items');
    }
}
